#!/usr/bin/env node
// Condense a captured conversation JSONL into a readable trace:
// timestamps, roles, text content, tool names + short inputs. Skips tool_result bodies.
import { readFileSync } from 'node:fs';

const file = process.argv[2];
const maxText = Number(process.argv[3] || 1400);
const lines = readFileSync(file, 'utf8').split('\n').filter(Boolean);

const clip = (s, n) => {
  s = String(s ?? '').replace(/\s+/g, ' ').trim();
  return s.length > n ? s.slice(0, n) + ` …[+${s.length - n}ch]` : s;
};

let prev = null;
for (const line of lines) {
  let e;
  try { e = JSON.parse(line); } catch { continue; }
  const ts = e.timestamp || e.ts || '';
  const t = ts ? new Date(ts) : null;
  let gap = '';
  if (t && prev) {
    const d = Math.round((t - prev) / 1000);
    if (d >= 30) gap = `  [+${d}s]`;
  }
  if (t) prev = t;
  const m = e.message || e;
  const role = m.role || e.type || '?';
  const content = m.content;
  const stamp = ts ? ts.replace('T', ' ').replace(/\..*/, '') : '';

  if (typeof content === 'string') {
    console.log(`\n--- ${stamp}${gap} ${role} ---\n${clip(content, maxText)}`);
    continue;
  }
  if (!Array.isArray(content)) {
    if (e.type && e.type !== 'user' && e.type !== 'assistant') {
      console.log(`\n--- ${stamp}${gap} <${e.type}> ---\n${clip(JSON.stringify(e).slice(0, 400), 400)}`);
    }
    continue;
  }
  const parts = [];
  for (const c of content) {
    if (c.type === 'text') parts.push(clip(c.text, maxText));
    else if (c.type === 'thinking') parts.push(`(thinking) ${clip(c.thinking, 600)}`);
    else if (c.type === 'tool_use') parts.push(`TOOL ${c.name}: ${clip(JSON.stringify(c.input), 300)}`);
    else if (c.type === 'tool_result') {
      const body = typeof c.content === 'string' ? c.content : JSON.stringify(c.content);
      parts.push(`RESULT${c.is_error ? ' (ERROR)' : ''}: ${clip(body, c.is_error ? 500 : 160)}`);
    }
  }
  if (parts.length) console.log(`\n--- ${stamp}${gap} ${role} ---\n${parts.join('\n')}`);
}

